	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/me/home", wrapper.GetHome)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/me/home", wrapper.ReplaceHome)
